const c = $('Compile Input Data').first().json;
const b = c.booking, m = c.meta;
const out = $input.first().json || {};

let ai = String(out.output || out.text || '').trim();
ai = ai.replace(/\*\*(.+?)\*\*/g, '*$1*').replace(/^#{1,6}\s*(.+)$/gm, '*$1*');
const aiError = out.error ? String(out.error.message || out.error) : (ai ? '' : 'empty AI output');

const header = ':calendar: *Demo Briefing - ' + b.name + ' (' + b.company + ')*\n' +
  '*When:* ' + b.booking_time_local + '  |  *Email:* ' + b.email + (b.job_title ? '  |  *Role:* ' + b.job_title : '') + '\n';

let body;
if (!aiError) {
  body = ai;
} else {
  body = ':warning: AI briefing unavailable (' + aiError + '). Raw context below.\n' +
    '*Stated problem:* ' + b.stated_problem + '\n' +
    (b.form_answers ? '*Form answers:* ' + b.form_answers + '\n' : '') +
    '*HubSpot:* ' + m.deals + ' deals, ' + m.tickets + ' tickets, ' + m.engagements + ' activities on record.';
}

const hsStatus = m.contact_found ? 'existing contact' : (m.contact_created ? 'new contact created' : 'no contact');
const footer = '\n_ID ' + m.booking_id + ' | HubSpot: ' + hsStatus + ', ' +
  m.deals + ' deals, ' + m.tickets + ' tickets, ' + m.engagements + ' activities | Research: ' + m.research_ok + '/' + m.research_total + ' sources_';

return [{ json: {
  slack_text: (header + '\n' + body + '\n' + footer).slice(0, 3800),
  ai_output: ai,
  ai_error: aiError,
  status: aiError ? 'Briefed (AI fallback)' : 'Briefed'
} }];

const plan = $('Construct Research Plan').all().map(i => i.json);
const context = plan[0].context;
const results = $('Perform Web Research').all().map(i => i.json);

const research = plan.map((t, i) => {
  const r = results[i] || {};
  const raw = typeof r.data === 'string' ? r.data : (typeof r.body === 'string' ? r.body : '');
  const ok = !r.error && raw.length > 80;
  return {
    label: t.label,
    source: t.url.replace('https://r.jina.ai/', ''),
    ok,
    text: ok ? raw.replace(/\s+/g, ' ').slice(0, 3000) : '',
    error: r.error ? String(r.error.message || r.error) : (ok ? '' : 'empty response')
  };
});

const h = context.hubspot;
const list = (arr, f) => arr.length ? arr.map(f).join('\n') : '(none found)';

let contactStatusText = '(no contact found in HubSpot - treat as new prospect)';
if (h.contact_found) {
  contactStatusText = 'Existing Contact: ' + JSON.stringify(h.contact);
} else if (h.contact_created) {
  contactStatusText = 'Newly Created Lead (no prior contact history): ' + JSON.stringify(h.contact);
}

const parts = [
  '## BOOKING\n' + JSON.stringify(context.booking, null, 2),
  '## HUBSPOT CONTACT\n' + contactStatusText,
  '## HUBSPOT DEALS\n' + list(h.deals, d => '- ' + d.name + ' | amount: ' + (d.amount ?? 'n/a') + ' | stage: ' + (d.stage ?? 'n/a') + ' | closes: ' + (d.closeDate ?? 'n/a') + ' | modified: ' + (d.lastModified ?? 'n/a') + (d.description ? ' | ' + d.description : '')),
  '## HUBSPOT TICKETS\n' + list(h.tickets, t => '- ' + t.subject + ' | stage: ' + (t.stage ?? 'n/a') + ' | priority: ' + (t.priority ?? 'n/a') + ' | created: ' + (t.created ?? 'n/a') + (t.content ? ' | ' + t.content : '')),
  '## HUBSPOT EMAILS / NOTES / MEETINGS / CALLS (newest first)\n' + list(h.engagements, e => '- [' + e.type + ' ' + (e.date ?? '') + '] ' + (e.subject ? e.subject + ': ' : '') + e.text),
  ...research.map(r => '## WEB RESEARCH: ' + r.label + ' (' + r.source + ')\n' + (r.ok ? r.text : '(unavailable: ' + r.error + ')'))
];

return [{ json: {
  agent_input: parts.join('\n\n'),
  booking: context.booking,
  meta: {
    booking_id: context.booking.booking_id,
    booking_key: $('Validate and Deduplicate Data').first().json.booking_key,
    contact_found: h.contact_found,
    contact_created: h.contact_created,
    deals: h.deals.length, tickets: h.tickets.length, engagements: h.engagements.length,
    research_ok: research.filter(r => r.ok).length, research_total: research.length
  }
} }];

const v = $('Validate and Deduplicate Data').first().json;
const norm = x => (x === undefined || x === null) ? '' : String(x);
const strip = s => norm(s).replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const prop = (o, k) => { const p = o && o.properties && o.properties[k]; return (p && typeof p === 'object' && 'value' in p) ? p.value : p; };
const safeAll = name => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };

// ---- HubSpot contact (check Search first, then fallback to newly Created contact)
const searchedContact = safeAll('Search HubSpot Contact').find(j => j && (j.id || j.vid)) || null;
const createdContact = safeAll('Create HubSpot Contact').find(j => j && (j.id || j.vid)) || null;
const contact = searchedContact || createdContact;
const contactId = contact ? norm(contact.id || contact.vid) : '';
const isNewContact = !searchedContact && !!createdContact;

// ---- relevance: associated to contact, OR mentions company / email-domain label
const FREE = ['gmail', 'yahoo', 'outlook', 'hotmail', 'icloud', 'proton', 'protonmail', 'aol', 'live', 'rediffmail'];
const domainLabel = (v.email.split('@')[1] || '').split('.')[0].toLowerCase();
const tokens = [v.company.toLowerCase(), FREE.includes(domainLabel) ? '' : domainLabel].filter(t => t.length >= 3);
const hasId = (obj, id) => !!id && new RegExp('(^|\\D)' + id + '(\\D|$)').test(JSON.stringify(obj || {}));
const mentions = text => { const t = norm(text).toLowerCase(); return tokens.some(k => t.includes(k)); };
const relevant = (assoc, text) => hasId(assoc, contactId) || mentions(text);

const deals = safeAll('Get HubSpot Deals')
  .filter(d => d && (d.id || d.dealId))
  .filter(d => relevant(d.associations, [prop(d, 'dealname'), prop(d, 'description')].map(norm).join(' ')))
  .sort((a, b) => norm(prop(b, 'hs_lastmodifieddate')).localeCompare(norm(prop(a, 'hs_lastmodifieddate'))))
  .slice(0, 10)
  .map(d => ({
    name: prop(d, 'dealname'), amount: prop(d, 'amount'), stage: prop(d, 'dealstage'),
    pipeline: prop(d, 'pipeline'), closeDate: prop(d, 'closedate'),
    lastModified: prop(d, 'hs_lastmodifieddate'), description: strip(prop(d, 'description')).slice(0, 300)
  }));

const tickets = safeAll('Get HubSpot Tickets')
  .filter(t => t && (t.id || t.ticketId))
  .filter(t => relevant(t.associations, [prop(t, 'subject'), prop(t, 'content')].map(norm).join(' ')))
  .slice(0, 10)
  .map(t => ({
    subject: prop(t, 'subject'), content: strip(prop(t, 'content')).slice(0, 300),
    stage: prop(t, 'hs_pipeline_stage'), priority: prop(t, 'hs_ticket_priority'), created: prop(t, 'createdate')
  }));

const engagements = safeAll('Get HubSpot Engagements')
  .filter(e => e && e.engagement)
  .filter(e => hasId(e.associations && e.associations.contactIds, contactId))
  .sort((a, b) => (b.engagement.timestamp || 0) - (a.engagement.timestamp || 0))
  .slice(0, 15)
  .map(e => {
    const m = e.metadata || {};
    return {
      type: e.engagement.type,
      date: e.engagement.timestamp ? new Date(e.engagement.timestamp).toISOString().slice(0, 10) : null,
      subject: m.subject || m.title || null,
      text: strip(m.text || m.body || m.html || e.engagement.bodyPreview).slice(0, 500)
    };
  });

const context = {
  booking: {
    booking_id: v.booking_id, name: v.name, email: v.email, company: v.company, website: v.website || null,
    job_title: v.job_title || null, phone: v.phone || null,
    stated_problem: v.stated_problem, form_answers: v.form_answers || null,
    booking_time_local: v.booking_time_local, meeting_in_minutes: v.meeting_in_minutes
  },
  hubspot: {
    contact_found: !!searchedContact,
    contact_created: isNewContact,
    contact: contact ? {
      id: contactId,
      firstname: prop(contact, 'firstname') || v.name.split(' ')[0],
      lastname: prop(contact, 'lastname') || v.name.split(' ').slice(1).join(' '),
      jobtitle: prop(contact, 'jobtitle') || v.job_title,
      company: prop(contact, 'company') || v.company,
      lifecyclestage: prop(contact, 'lifecyclestage') || 'lead',
      lead_status: prop(contact, 'hs_lead_status') || null
    } : null,
    deals, tickets, engagements
  }
};

// ---- research plan: one item per task, processed sequentially + throttled by the HTTP node
const search = q => 'https://r.jina.ai/https://html.duckduckgo.com/html/?q=' + encodeURIComponent(q);
const tasks = [
  { label: 'company_overview', url: search(v.company + ' company what do they do') },
  { label: 'company_news', url: search(v.company + ' latest news') },
  { label: 'problem_context', url: search(v.stated_problem.slice(0, 140) + ' how to solve') }
];
if (v.website) tasks.push({ label: 'company_website', url: 'https://r.jina.ai/' + v.website });

return tasks.map((t, i) => ({ json: i === 0 ? { ...t, context } : t }));

// ---- config -------------------------------------------------------------
const REP_TZ = 'Asia/Kolkata';         // timezone shown to the sales rep
const SHARED_SECRET = '';              // set a value to require header: x-webhook-secret
const DEDUPE_WINDOW_MS = 6 * 60 * 60 * 1000;

const input = $input.first().json;
const b = input.body || {};
const headers = input.headers || {};
const str = v => (v === undefined || v === null) ? '' : String(v).trim();

const name = str(b.name);
const email = str(b.email).toLowerCase();
const company = str(b.company);
const problem = str(b.stated_problem || b.problem);
const bookingRaw = str(b.booking_time);
let website = str(b.website);
if (website && !/^https?:\/\//i.test(website)) website = 'https://' + website;
if (website && !/^https?:\/\/[^\s.]+\.[^\s]+$/i.test(website)) website = '';

const errors = [];
if (SHARED_SECRET && headers['x-webhook-secret'] !== SHARED_SECRET) errors.push('unauthorized');
if (!name) errors.push('name is required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('a valid email is required');
if (!company) errors.push('company is required');
if (!problem) errors.push('stated_problem is required');
const bt = new Date(bookingRaw);
if (!bookingRaw || isNaN(bt.getTime())) errors.push('booking_time must be a valid ISO date-time');

const valid = errors.length === 0;
const bookingIso = valid ? bt.toISOString() : '';
const bookingKey = valid ? email + '|' + bookingIso : '';

let h = 5381;
for (const ch of bookingKey) h = ((h << 5) + h + ch.charCodeAt(0)) >>> 0;
const bookingId = valid ? 'BK-' + h.toString(36).toUpperCase().padStart(7, '0') : '';

// ---- idempotency guard (persisted in workflow static data, production runs only)
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
for (const k of Object.keys(store.seen)) if (now - store.seen[k] > DEDUPE_WINDOW_MS) delete store.seen[k];
const duplicate = valid && !b.force && !!store.seen[bookingKey];
const proceed = valid && !duplicate;
if (proceed) store.seen[bookingKey] = now;

let statusCode = 202;
if (errors.includes('unauthorized')) statusCode = 401;
else if (!valid) statusCode = 400;
else if (duplicate) statusCode = 200;

let formAnswers = b.form_answers || b.answers || '';
if (formAnswers && typeof formAnswers === 'object') formAnswers = JSON.stringify(formAnswers);

return [{ json: {
  proceed, valid, duplicate, errors, status_code: statusCode,
  booking_id: bookingId, booking_key: bookingKey,
  name, email, company, website,
  job_title: str(b.job_title), phone: str(b.phone),
  stated_problem: problem, form_answers: str(formAnswers),
  booking_time: bookingIso,
  booking_time_local: valid ? bt.toLocaleString('en-IN', { timeZone: REP_TZ, dateStyle: 'medium', timeStyle: 'short' }) + ' (' + REP_TZ + ')' : '',
  meeting_in_minutes: valid ? Math.round((bt.getTime() - now) / 60000) : null,
  received_at: new Date(now).toISOString()
} }];
